    // threadIdx.y splits the reduction dimension across multiple threads to
    // increase memory-level parallelism. Each thread now handles VEC contiguous
    // inner elements at once, opportunistically using 16-byte (float4) vectorized
    // loads when the resulting address is properly aligned (falling back to safe
    // scalar __ldg loads otherwise), reducing the number of load instructions for
    // the large reduce_size while preserving full correctness for arbitrary shapes.
    constexpr int VEC = 4;
    extern __shared__ unsigned char smem_raw[];
    T* sdata = reinterpret_cast<T*>(smem_raw);
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const long tile_inner_base = (long)blockIdx.x * (long)blockDim.x * VEC;
    const long inner_idx0 = tile_inner_base + (long)tx * VEC;
    int valid_count = 0;
    if (inner_idx0 < inner_size) {
        long remaining = inner_size - inner_idx0;
        valid_count = remaining < VEC ? (int)remaining : VEC;
    }
    const int stride_elems = (int)blockDim.x * VEC;
    for (long outer_idx = blockIdx.y; outer_idx < outer_size; outer_idx += (long)gridDim.y) {
        T maxval[VEC];
        #pragma unroll
        for (int k = 0; k < VEC; ++k) maxval[k] = (T)(-FLT_MAX);
        if (valid_count > 0) {
            const T* __restrict__ row_base = X + outer_idx * reduce_size * inner_size + inner_idx0;
            for (long r = (long)ty; r < reduce_size; r += (long)blockDim.y) {
                const T* __restrict__ ptr = row_base + r * inner_size;
                if (valid_count == VEC && ((reinterpret_cast<uintptr_t>(ptr) & 0xF) == 0)) {
                    float4 v4 = *reinterpret_cast<const float4*>(ptr);
                    maxval[0] = v4.x > maxval[0] ? v4.x : maxval[0];
                    maxval[1] = v4.y > maxval[1] ? v4.y : maxval[1];
                    maxval[2] = v4.z > maxval[2] ? v4.z : maxval[2];
                    maxval[3] = v4.w > maxval[3] ? v4.w : maxval[3];
                } else {
                    #pragma unroll
                    for (int k = 0; k < VEC; ++k) {
                        if (k < valid_count) {
                            T v = __ldg(ptr + k);
                            maxval[k] = v > maxval[k] ? v : maxval[k];
                        }
                    }
                }
            }
        }
        const int base_idx = ty * stride_elems + tx * VEC;
        #pragma unroll
        for (int k = 0; k < VEC; ++k) sdata[base_idx + k] = maxval[k];
