                const int other_idx = (ty + offset) * stride_elems + tx * VEC;
                #pragma unroll
                for (int k = 0; k < VEC; ++k) {
                    T other = sdata[other_idx + k];
                    T cur = sdata[cur_idx + k];
                    sdata[cur_idx + k] = other > cur ? other : cur;
                }
            }
            __syncthreads();
        }
        if (ty == 0 && valid_count > 0) {
